-- 分解界面说明文字
_Decompose_tip_info = "1.點擊“+”進入選擇介面，每次可最多選擇5個忍者、裝備、寶物或時裝進行分解。\r\n2.只可分解4星及以上未成長的忍者，分解後返還所有升級花費並獲得獸魂。\r\n3.可分解3星和4星裝備，分解後返還所有升級花費並獲得覺醒書。\r\n4.可分解5星裝備，分解後返還所有升級花費並獲得橙裝鑄造材料。\r\n5.只可分解5星寶物，分解後可獲得靈氣精華並返還所有強化經驗(返還的經驗在分解獲得的藍色經驗寶物中)\r\n6.分解時裝可獲得時裝精華\r\n7.分解後，所分解的忍者、裝備、寶物或時裝將會消失。"


-- 退化界面说明文字
_Regeneration_tip_info = "1.點擊“+”進入選擇介面，每次只可選擇1個忍者、裝備、寶物或時裝進行退化。\r\n2.可退化強化等級在2級及以上的4星忍者和5星忍者，退化後返還所有花費(成長所消耗的銅幣不返還)，退化後的忍者恢復成長等級為0階，強化等級為1級。\r\n3.可退化6星忍者，退化後變為5星+7，等級不變，並返還成長和橙色成長所消耗的所有銅幣及材料。\r\n4.只可退化5星且強化等級大於0的裝備，退化後返還所有強化費用，並根據洗煉屬性返還覺醒書。\r\n5.只可退化強化等級大於0的時裝，退化後返還所有強化費用和時裝精華。\r\n6.只可退化4星及以上，強化過的寶物，退化後返還所有升級花費，並根據寶物等級返還經驗寶物和覺醒寶物\r\n7.每次退化需要花費一定銅幣。"


-- 灵异探险界面的说明文字
_Divine_explain_tip_info = "1.點亮靶心圖表案上的所有圖案或點擊任何圖案都可以獲得星數獎勵。\r\n\r\n2.通過獲得的星數可兌換獎勵，星數越多兌換的獎勵越多。\r\n\r\n3.每日淩晨0點重置探險次數、當前星數及獎勵。"

-- 限时队长级说明文字
_Limited_hero_tip_info = "1.在活動介面中使用免費抽取或者銅幣抽取忍者即可獲得10積分。\r\n2.每累積獲得150積分，即可獲得1次免費銅幣抽取次數。\r\n3.每次抽取可隨機獲得4星或5星忍者，5星忍者中包含限時活動忍者。\r\n4.活動結束時，根據積分排名，將會發放排名獎勵。\r\n5.玩家每達到1000積分時必定抽中當前限時隊長。\r\n6.積分達到60分的玩家將額外獲得：10個金經驗獸，銅幣20萬，500個成長石(該獎勵與排名獎勵可同時獲得)\r\n活動結束的當天內獎勵即會發放，通過獎勵中心領取。"

-- 超级变变变说明文字(限时兑换)
_Super_change_tip_info = "1.活動期間內，玩家可使用指定的物品進行兌換，獲得新的物品；\r\n2.可使用未強化過的裝備或寶物進行兌換；\r\n3.兌換後會失去原有物品並獲得兌換後的新物品。"

-- 分段折扣说明文字
_Divide_sell_tip_info = "1.活動期間根據全服購買的指定道具數量對該道具進行打折。\r\n2.當指定道具消耗數量達到指定數量時，商店內出售的該道具價格也將相應的發生變化。\r\n"

-- 跨服幸运大转盘说明文字
_Luck_turntable_tip_info = "1.活動期間使用免費或銅幣轉動幸運大轉盤都可獲得1積分，活動結束後會根據積分排名發放對應獎勵；\r\n2.免費次數不會累加，免費次數使用後12小時會恢復；\r\n3.活動期間使用免費或銅幣轉動幸運大轉盤都會增加一點次數獎勵進度條，達到對應次數可立刻領取獎勵；\r\n4.每天有5次免費刷新機會可刷新轉盤上的獎勵，免費次數用完後可使用銅幣刷新，當玩家抽中高級道具時會強制刷新轉盤；\r\n5.免費刷新或使用銅幣刷新都有機會刷出高級限量道具(限量道具售光後無法再刷出)；\r\n6.免費轉動或使用銅幣轉動幸運大轉盤都有機會獲得幸運大獎；\r\n7.系統會將玩家轉動轉盤消耗的銅幣按一定比例累加到幸運大獎獎池，累加無上限；\r\n8.當玩家轉到幸運大獎後，將會獨得獎池內一定比例的銅幣大獎；\r\n9.幸運大轉盤資料所有伺服器互通。"

-- 灵王宫说明文字
_spirite_palace_tip_info = "1.每天可獲得一次免費重置機會(不可累加)；\r\n2.靈王宮共有五層，每層達到可移動次數上限後就出現下一層入口，達到第五層終點即完成本輪探險；\r\n3.點擊岔道口的事件圖示可以查看事件說明，點擊移動可觸發該事件，或直接點擊下方箭頭進行移動；\r\n4.每觸發一個事件都會獲得一定的積分，積分可在靈王宮商店兌換道具；\r\n5.每次移動都會消耗1點行動力，行動力為0時不可再移動；\r\n6.首次進入靈王宮或重置後，會根據玩家當前陣容確定當前探險陣型，探險陣型一旦確定，本次探險過程中將無法進行改變；\r\n7.首次進入靈王宮或重置後，會根據玩家當前陣容所有忍者生命之和的三倍生成一條血槽，玩家在探險過程中會遭遇戰鬥，戰鬥結束後會根據忍者的損血量消耗血槽進行補充，如果血槽降到0便無法繼續探險。"

-- 跨服战说明文字
_cross_server_tip_info = "【更新戰鬥資訊】\r\nA)戰鬥資訊\r\n是指跟玩家戰鬥相關的資料，即上陣忍者、裝備、鬼道、陣型等所有可以影響玩家戰鬥強弱的相關資訊。\r\nB)更新戰鬥資訊\r\n玩家每次變動戰鬥資訊後需要點擊“更新戰鬥資訊”來向跨界爭霸戰遊戲伺服器上傳最新的戰鬥資訊，否則遊戲伺服器上的玩家戰鬥資訊不會改變。\r\n【跨界爭霸戰規則】\r\nA)先手規則\r\n戰鬥力高的玩家為先手\r\nB)海選賽規則\r\n1、瀞靈廷組海選賽規則\r\n1)隨機分配對手，每場1局，每場間隔10分鐘\r\n2)玩家不會再遇到已出局的對手\r\n3)如果玩家累積失敗3場則被淘汰出局，直至決出最後32強\r\n4)玩家可以在我的資訊中“我的戰績”處查看自己的戰績\r\n2、流魂街組海選賽規則\r\n1)瀞靈廷組海選賽結束後，去除瀞靈廷組出線的選手，其他玩家進行流魂街組海選賽\r\n2)隨機分配對手，每場1局，每場間隔10分鐘\r\n3)玩家不會再遇到已出局的對手\r\n4)如果玩家累積失敗3場則被淘汰出局，直至決出最後32強，海選結束\r\n5)玩家可以在我的資訊中“我的戰績”處查看自己的戰績\r\nC)晉級賽規則\r\n1、海選賽出線的瀞靈廷32強和流魂街32強分成16組，以每組2人進行5局3勝的比賽，獲得3場勝利的玩家晉級，每局間隔20分鐘\r\n2、每場晉級賽間隔1天\r\n3、瀞靈廷組和流魂街組分別決出各自組的冠軍\r\n4、進入晉級賽的玩家自動進入跨服跨界爭霸賽的海選\r\n【跨服跨界爭霸賽規則】\r\nA)先手規則\r\n戰鬥力高的玩家為先手\r\nB)海選賽規則\r\n1、瀞靈廷組海選賽規則\r\n1)隨機分配對手，每場1局，每場間隔10分鐘\r\n2)玩家不會再遇到已出局的對手\r\n3)如果玩家累積失敗3場則被淘汰出局，直至決出最後32強\r\n4)玩家可以在我的資訊中“我的戰績”處查看自己的戰績\r\n2、流魂街組海選賽規則\r\n1)瀞靈廷組海選賽結束後，去除瀞靈廷組出線的選手，其他玩家進行流魂街組海選賽\r\n2)隨機分配對手，每場1局，每場間隔10分鐘\r\n3)玩家不會再遇到已出局的對手\r\n4)如果玩家累積失敗3場則被淘汰出局，直至決出最後32強，海選結束\r\n5)玩家可以在我的資訊中“我的戰績”處查看自己的戰績\r\nC)晉級賽規則\r\n1、海選賽出線的瀞靈廷32強和流魂街32強分成16組，以每組2人進行5局3勝的比賽，獲得3場勝利的玩家晉級，每局間隔20分鐘\r\n2、每場晉級賽間隔1天\r\n3、瀞靈廷組和流魂街組分別決出各自組的冠軍\r\n4、跨服跨界爭霸賽瀞靈廷組冠軍所在伺服器所有玩家可獲得禮包獎勵\r\n【助威規則】\r\n晉級賽階段，每場晉級賽玩家只可為1名玩家助威，被助威的玩家如果進入下一輪比賽，則助威的玩家可獲得助威獎勵。每場晉級賽結束後發放助威獎勵，當獎勵發放完畢後，可進行下一場晉級賽的助威。"

-- 副队长说明文字
_vice_captain_tip_info = "1.上陣中的副隊長，每隔一段時間獲得一定經驗；\r\n2.只有上陣中的副隊長纔可進行出戰操作，出戰的副隊長可在戰前將自身技能屬性提供給上陣忍者；\r\n3.一次只能出戰一名副隊長；\r\n4.培養可增加副隊長經驗，當副隊長升到一定等級時可獲得技能點；\r\n5.技能點可用來開啟技能槽、領悟技能、升級技能。"

--侵略者帮助奖励文字
_betray_army_reward_tip_info = "1.光丘守護可獲得功勳獎勵，主要是大量銅幣、晶片石和橙色經驗寶物。\r\n2.光丘守護還可獲得戰功，戰功可在戰功商店購買稀有忍者和晶片石。"

--侵略者帮助功勋文字
_betray_army_exploit_tip_info = "1.35級後，每次挑戰主線副本和精英副本都有概率發現侵略者，可以單獨或邀請好友一起光丘守護。\r\n2.每次光丘守護會獲得功勳值，傷害越高功勳值越多，忍者每成長+1對侵略者傷害提升2.5倍！\r\n3.若擊殺侵略者，發現侵略者的玩家和給予最後一擊的玩家都可獲得銅幣獎勵。"

--侵略者帮助战功文字
_betray_army_credit_tip_info = "1.攻打侵略者時，每消耗一個挑戰書，都可獲得50戰功。\r\n2.若進入光丘守護的每日功勳榜和每日傷害榜前200名，還可獲得額外的排名戰功獎勵。\r\n3.每天12:00-14:00怒攻只消耗1個挑戰書，18:00-20:00攻打侵略者功勳翻倍。"

--组织资源抢夺帮助信息
_capture_resource_tip_info = "1.擊敗建築守衛者可佔領該建築，並可獲得資源產出獎勵；\r\n2.每名玩家可同時佔領多個建築，相鄰的建築可獲得資源產出加成；\r\n3.每個建築有對應的佔領條件，佔領建築的陣容為臨時組建陣容，跟原有陣容相互獨立；\r\n4.可派出原陣容中已上陣的忍者，不會計算裝備和寶物屬性，緣分會按照新的上陣情況重新計算；\r\n5.佔領成功後，所派出的忍者將成為建築守衛，不可中途更換；\r\n6.攻打建築或佔領建築可獲得積分，每週二和每週五中午12點會根據積分排名發放獎勵，並清空積分；\r\n7.攻打建築無論勝利失敗可獲得5積分，佔領建築後每分鐘可獲得1積分(佔領結束時根據佔領時間獲得)；\r\n8.排名獎勵需要玩家自行進入獎勵頁面領取，獎勵會保存到下一次排行結算，結算時會刪除未領取的獎勵(積分為0的玩家無法獲得獎勵)。"

---组织战帮助信息
_union_fight_tip_info = "報名階段：\r\n1.週三3點開啟報名；\r\n2.加入組織48小時的成員才能參與組織戰；\r\n3.組織戰為跨服戰鬥，會根據組織戰力匹配對手。\r\n\r\n準備階段：\r\n1.週四3點開啟準備階段；\r\n2.首領和副首領可部署防守陣型；\r\n3.組織成員在前後城各擁有一個防守格；\r\n4.暗格在被攻擊前處於資訊不明狀態。\r\n\r\n戰鬥階段：\r\n1.週五3點開啟戰鬥，22點結算戰鬥；\r\n2.每人3次嘗試進攻機會，2次擊殺次數；\r\n3.守衛為1的據點進入【失守】狀態，可被通過；\r\n4.守衛為0的據點進入【攻陷】狀態，可取得積分；\r\n5.特殊據點包含額外獎勵，攻陷該據點後可領取；\r\n6.結算時積分高的組織獲勝，如果積分相同，戰力低的組織獲勝；\r\n7.勝利或失敗的組織都會獲得獎勵，失敗的獎勵是勝利的一半。"


