_union_info = {
	"組織功能介紹",
	"1.組織成員上限：Lv1-30、Lv2-32、Lv3-34……",
	"2.組織等級提升：組織經驗可用於提升組織等級，可透過組織副本和捐獻獲得組織經驗。",
	"3.組織等級提升後可以開啟新的組織副本，提高建設進度獎勵，在組織商店中也會開放更多獎勵道具。",
	"4.成員可以從組織建設和組織副本中獲得組織貢獻，組織貢獻可以在組織商店中購買各種道具。",
	"5.組織貢獻：可透過組織副本和組織捐獻獲得，可在組織商店購買道具。",
	"6.組織首領：組織成員少於10人時，首領可解散組織；首領最多可任命2名副首領，首領和副首領均享有以下權限：審核新成員、踢出成員、編輯組織公告和宣言等。",
	"7.組織成員：加入後24小時內不可被踢出。",
	"8.創建組織7日內，組織成員數不足3人，並且組織等級為1級時，組織會自動解散。",
	"組織建設",
	"1.建設模式：初級建設、普通建設和高級建設。組織成員每天可選擇一種模式進行建設。",
	"2.建設過程中，有機率觸發增益，獲得150%組織貢獻和組織經驗（額外加成不計入進度）",
	"3.組織進度到達對應要求後，全體組織成員均可領取建設進度獎勵。",
	"4.組織等級越高，建設進度獎勵越豐厚。",
	"5.需注意，每天24:00系統會自動清空當天的建設進度獎勵。",
	"6.每天的建設次數不能超過組織成員數上限。",
}



