national_truce_dec =  --国战说明
{
	{"【規則】","勢力戰領地分為龍虎門領地、白蓮教領地、羅剎教領地、中立區4個區域。"},
	{"","每個勢力有一個主神像，主神像無法被攻陷，玩家陣亡時，會被傳送至主神像復活。"},
	{"","殺死據點中最後一個NPC，則該玩家所屬的勢力視為佔領據點的勢力,活動期間已經被佔領的據點可以繼續被搶奪。"},
	{"","若同一個據點有超過兩股以上的勢力同時爭奪，則在此據點範圍內的玩家，既可以攻擊守衛據點的NPC，也可以攻擊正在攻擊據點的其他勢力玩家。"},
	{"","不論攻守雙方人數差距多大，佔領據點的條件永遠是“擊殺該據點最後一個守衛據點的NPC”，一旦據點易主，將清空該據點內所有其他勢力的玩家，這些玩家將被強制傳送回主神像。"},
	{"","當滿足一定條件時，玩家可以選擇進行一些戰術移動，如突進、包圍等。"},
	{"","勢力戰結束時，佔領據點最多的勢力視為勢力戰的最終勝利勢力。"},
	{"","勢力戰結束時，佔領據點最多的勢力視為勢力戰的最終勝利勢力。"},
	{"【戰鬥】","【等待】當玩家進入某領地後，自動進入等候狀態，等候狀態下可以被敵方玩家匹配到，匹配到後進入戰鬥。"},
	{"","【尋敵】點擊攻擊後，進入主動匹配敵方目標狀態，每次點擊攻擊後會有10秒的攻擊冷卻時間。攻擊可以選擇特定勢力的玩家進行攻擊。"},
	{"","【戰鬥】尋敵模式下，勝利後會有增加30秒的CD時間，當時間累積到1分鐘後，進入冷卻狀態，冷卻狀態下不可主動攻擊，花費200氣勢值可以清除CD。戰鬥勝利後，玩家的忍者不會回復已損失的血量，但查克拉會重置。"},
	{"","【陣亡】戰鬥失敗後，進入陣亡狀態，陣亡狀態下，不可進行指令相關操作。"},
	{"","【復活】陣亡後，傳送回主神像等待1分鐘的復活CD，可以花費500氣勢值立即復活。"},
	{"","【撤退】玩家可以花費200點氣勢值和損失最大生命值20%的生命為代價，強行從交戰中的領地中撤退。"},
	{"","【突進】進攻人數高於防守人數兩倍時，可採取突進戰術。"},
	{"","【包圍】當一個據點周圍的據點被其他勢力佔領時，該據點內防守方造成傷害降低50%、承受傷害增加50%。"},
	{"","【召集】武神、戰神、和鬥神可發佈召集令，號令本勢力成員迅速集合攻打目標據點。"},
	{"","【扶弱】勢力戰獲得第二名，下次勢力戰增加1500氣勢值，獲得第三名，下次勢力戰增加3000氣勢值。"},
	{"","【同盟】當一個勢力連續兩次獲得勢力戰第一，或同一個勢力連續兩次獲得勢力戰第三，上次勢力戰的二、三名自動結盟。"},
	{"","【盟約】勢力戰結算時，同盟兩勢力的據點數和總榮譽將相加進行排名，擊殺同盟勢力的玩家的個人榮譽減半。"},
	{"【獎勵】","榮譽值少於50點的玩家無法領取任務獎勵。"},
	{"","勢力戰結束時，會給據勢力所佔領地數量的排行，給與勢力戰中獲得50點榮譽以上的本玩家一定的獎勵，排名不同，獎勵不同。"},
	{"","勢力戰結束時，跟根據個人在本榮譽排行中的位置，給與一定的獎勵 。"},
}

