-- 抓真身规则说明
-- Clone Breach Rules 
_activity_smoked_eggs_rule_tips = {
    "1. 活動期間，每累計儲值60金幣可獲得1個抓真身用的苦無，每日最多10個苦無。\r\n\r\n2. 抓真身1倍需消耗兩*30000和苦無*1，有機率獲得3倍、6倍和10倍獎勵，即兩*90000、兩*180000、兩*300000。\r\n\r\n3.找到真身即可獲得10倍獎勵，之後3個分身全部重置；否則可繼續嘗試尋找真身。\r\n\r\n4.運氣好的話，1次就能找到真身並獲得10倍獎勵；否則3次內必定獲得10倍獎勵。 ",
